function callers(name,fp){
 const t=db.prepare('select id,qualified_name,signature from nodes where name=? and file_path=?').all(name,fp);
 console.log('===',name,fp,t[0].qualified_name,'|',t[0].signature);
 const rows=db.prepare(\"select s.name, s.file_path, count(*) c from edges e join nodes s on s.id=e.source where e.target=? and e.kind='calls' group by s.id order by s.file_path\").all(t[0].id);
 const byfile={}; rows.forEach(r=>byfile[r.file_path]=(byfile[r.file_path]||0)+1);
 console.log(Object.entries(byfile).map(([k,v])=>k+':'+v).join('\n'));
 console.log('distinct callers',rows.length);
}
